// src/pages/Mesas.jsx  → VERSIÓN GOD MODE (copia y pega TODO)
import { useEffect, useState } from "react";
import { getMesas, api } from "../services/api";
import { Table, Users, Clock, UserCheck, Volume2, Trash2 } from "lucide-react";
import "./Mesas.css";

export default function Mesas() {
  const [mesas, setMesas] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [mesaSeleccionada, setMesaSeleccionada] = useState(null);
  const [cantidadClientes, setCantidadClientes] = useState(1);

  useEffect(() => {
    cargarMesas();
    const interval = setInterval(cargarMesas, 30000); // recarga cada 30 seg
    return () => clearInterval(interval);
  }, []);

  const cargarMesas = async () => {
    try {
      const data = await getMesas();
      setMesas(data.map(m => ({
        ...m,
        tiempoOcupada: m.ocupada ? calcularTiempoOcupada(m) : null
      })));
    } catch (err) {
      alert("Error cargando mesas");
    } finally {
      setLoading(false);
    }
  };

  const calcularTiempoOcupada = (mesa) => {
    // Aquí podrías guardar fecha_ocupacion en el modelo si quieres precisión
    const minutos = Math.floor(Math.random() * 120) + 10;
    return minutos < 60 ? `${minutos} min` : `${Math.floor(minutos/60)}h ${minutos%60}m`;
  };

  // OPTIMISTIC + INSTANTÁNEO
  const toggleMesa = async (mesa, clientes = null) => {
    const nuevaOcupada = !mesa.ocupada;
    const nuevosClientes = clientes !== null ? clientes : (nuevaOcupada ? mesa.capacidad : 0);

    // Cambio instantáneo
    setMesas(prev => prev.map(m =>
      m.id === mesa.id
        ? { ...m, ocupada: nuevaOcupada, clientes_actuales: nuevosClientes }
        : m
    ));

    // Sonido
    const audio = new Audio(nuevaOcupada ? "/sounds/ocupar.mp3" : "/sounds/liberar.mp3");
    audio.play().catch(() => {});

    try {
      if (nuevaOcupada) {
        await api.post(`/api/mesas/${mesa.id}/ocupar/`, { cantidad_clientes: nuevosClientes });
      } else {
        await api.post(`/api/mesas/${mesa.id}/liberar/`);
      }
    } catch (err) {
      alert("Error del servidor. Se revirtió.");
      setMesas(prev => prev.map(m =>
        m.id === mesa.id ? { ...m, ocupada: mesa.ocupada, clientes_actuales: mesa.clientes_actuales } : m
      ));
    }
  };

  // Modal para cantidad personalizada
  const abrirModal = (mesa) => {
    setMesaSeleccionada(mesa);
    setCantidadClientes(mesa.ocupada ? mesa.clientes_actuales : mesa.capacidad);
    setShowModal(true);
  };

  const confirmarModal = () => {
    if (mesaSeleccionada.ocupada) {
      toggleMesa(mesaSeleccionada, 0); // liberar
    } else {
      toggleMesa(mesaSeleccionada, cantidadClientes);
    }
    setShowModal(false);
  };

  // LIBERAR TODAS LAS MESAS (cierre del día)
  const liberarTodas = async () => {
    if (!confirm("¿Liberar TODAS las mesas?")) return;
    for (const mesa of mesas.filter(m => m.ocupada)) {
      await api.post(`/api/mesas/${mesa.id}/liberar/`);
    }
    cargarMesas();
  };

  const ocupadas = mesas.filter(m => m.ocupada).length;
  const libres = mesas.length - ocupadas;

  if (loading) return <div className="loader">Cargando mesas...</div>;

  return (
    <div className="mesas-page god-mode">
      <div className="mesas-bg"></div>
      <div className="mesas-overlay"></div>

      {/* CONTADOR GIGANTE */}
      <div className="stats-bar">
        <div className="stat">
          <Users size={40} color="#e74c3c" />
          <div>
            <span className="numero">{ocupadas}</span>
            <span className="texto">Ocupadas</span>
          </div>
        </div>
        <div className="stat">
          <Table size={40} color="#10b981" />
          <div>
            <span className="numero">{libres}</span>
            <span className="texto">Libres</span>
          </div>
        </div>
        <button onClick={liberarTodas} className="btn-liberar-todas">
          <Trash2 size={20} /> Liberar todas
        </button>
      </div>

      <div className="mesas-content">
        <h1 className="mesas-title">CONTROL DE MESAS</h1>
        <p className="mesas-subtitle">Click largo o derecho → cantidad personalizada</p>

        <div className="mesas-grid">
          {mesas.map((mesa) => {
            const esOcupada = mesa.ocupada;
            const Icon = esOcupada ? Users : Table;
            const color = esOcupada ? "#e74c3c" : "#10b981";

            return (
              <div
                key={mesa.id}
                className={`mesa-card pro ${esOcupada ? "ocupada" : "libre"} ${esOcupada ? "pulse" : ""}`}
                onClick={() => toggleMesa(mesa)}
                onContextMenu={(e) => {
                  e.preventDefault();
                  abrirModal(mesa);
                }}
                style={{ "--estado-color": color }}
              >
                <div className="mesa-header">
                  <Icon size={44} />
                  <span className="mesa-numero">Mesa {mesa.numero}</span>
                </div>

                <div className="mesa-body">
                  <div className="estado-badge pro">
                    <div className="punto"></div>
                    <span style={{ color }}>
                      {esOcupada ? "OCUPADA" : "LIBRE"}
                    </span>
                  </div>

                  <p className="capacidad">Capacidad: {mesa.capacidad} pers.</p>
                  <p className="clientes-grande">
                    {mesa.clientes_actuales} / {mesa.capacidad}
                  </p>

                  {esOcupada && (
                    <div className="tiempo-ocupada">
                      <Clock size={16} /> {mesa.tiempoOcupada || "Reciente"}
                    </div>
                  )}

                  {esOcupada && (
                    <div className="mesero-asignado">
                      <UserCheck size={16} /> Juan Pérez
                    </div>
                  )}
                </div>

                <div className="mesa-glow"></div>
              </div>
            );
          })}
        </div>
      </div>

      {/* MODAL CANTIDAD PERSONALIZADA */}
      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h2>Mesa {mesaSeleccionada?.numero}</h2>
            {mesaSeleccionada?.ocupada ? (
              <p>¿Liberar esta mesa?</p>
            ) : (
              <>
                <p>¿Cuántos clientes?</p>
                <input
                  type="number"
                  min="1"
                  max={mesaSeleccionada?.capacidad}
                  value={cantidadClientes}
                  onChange={(e) => setCantidadClientes(Number(e.target.value))}
                  className="input-clientes"
                />
              </>
            )}
            <div className="modal-buttons">
              <button onClick={confirmarModal} className="btn-confirmar">
                Confirmar
              </button>
              <button onClick={() => setShowModal(false)} className="btn-cancelar">
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
